addQ("ing-k5-s17", 5, "Diet Herbivore Deer", "sedang", "A deer only eats tender green leaves, grass, and tree bark. A deer is a ...", ["Herbivore", "Carnivore", "Piscivore", "Scavenger"], 0, "Herbivora memakan material tumbuhan ('herbivore').");
addQ("ing-k5-s18", 5, "Ordering at Restaurant Would Like", "sedang", "Waiter: 'Good evening. What would you like to order?' Customer: 'I ... a plate of fried rice, please.'", ["Would like", "Would hate", "Did not want", "Do not like"], 0, "'I would like ...' adalah cara sopan memesan makanan di restoran.");
addQ("ing-k5-s19", 5, "Health Sore Throat", "sedang", "When it hurts to swallow food because your throat is infected, you have a ...", ["Sore throat", "Broken arm", "Toothache", "Stomachache"], 0, "Radang sakit tenggorokan adalah 'sore throat'.");
addQ("ing-k5-s20", 5, "Health Cough", "sedang", "A reflex that forces air out of your lungs with a sudden loud sound when you have a cold is a ...", ["Cough (batuk)", "Sneeze", "Hiccup", "Yawn"], 0, "Batuk adalah 'cough'.");

addQ("ing-k5-u01", 5, "Passive Voice Simple Present", "sulit", "Active: 'Budi cleans the classroom every morning.' Passive: 'The classroom ... by Budi every morning.'", ["Is cleaned", "Are cleaned", "Was cleaned", "Cleans"], 0, "Kalimat pasif present tense: Subject (singular) + is + V3 ('is cleaned').");
addQ("ing-k5-u02", 5, "Passive Voice Simple Present Plural", "sulit", "Active: 'The gardener waters the flowers.' Passive: 'The flowers ... by the gardener.'", ["Are watered", "Is watered", "Was watered", "Were water"], 0, "Objek jamak 'the flowers' menggunakan 'are watered'.");
addQ("ing-k5-u03", 5, "Passive Voice Simple Past", "sulit", "Active: 'Alexander Graham Bell invented the telephone.' Passive: 'The telephone ... by Alexander Graham Bell.'", ["Was invented", "Is invented", "Were invented", "Inventions"], 0, "Kalimat pasif lampau tunggal menggunakan 'was' + V3 ('was invented').");
addQ("ing-k5-u04", 5, "Past Continuous Tense Interrupted Action", "sulit", "I ... a book when my mother knocked on my bedroom door.", ["Was reading", "Were reading", "Am reading", "Read"], 0, "Aktivitas yang sedang berlangsung di masa lampau saat disela peristiwa lain menggunakan past continuous: 'was reading'.");
addQ("ing-k5-u05", 5, "Past Continuous Tense Plural", "sulit", "The students ... basketball on the court when the rain suddenly started to pour.", ["Were playing", "Was playing", "Are playing", "Played"], 0, "Subjek jamak 'The students' menggunakan 'were playing'.");
addQ("ing-k5-u06", 5, "Subject Verb Agreement Each Student", "sulit", "Every morning, each student in our school ... a blue badge on their uniform.", ["Wears", "Wear", "Wearing", "Are wearing"], 0, "'Each student' diperlakukan sebagai subjek tunggal sehingga kata kerja berakhiran -s ('wears').");
addQ("ing-k5-u07", 5, "Subject Verb Agreement Both Students", "sulit", "Both Budi and Edo ... excellent table tennis players.", ["Are", "Is", "Am", "Was"], 0, "'Both A and B' selalu menggunakan to be jamak ('are').");
addQ("ing-k5-u08", 5, "Comparative Irregular Farther", "sulit", "Surabaya is far from Jakarta, but Jayapura in Papua is much ... than Surabaya.", ["Farther / Further", "Farest", "More far", "Farrer"], 0, "Bentuk comparative dari 'far' adalah 'farther' atau 'further'.");
addQ("ing-k5-u09", 5, "Superlative Irregular Farthest", "sulit", "Neptune is the ... planet from the Sun in our solar system.", ["Farthest / Furthest", "Farther", "Most far", "More far"], 0, "Bentuk superlative dari 'far' adalah 'farthest' atau 'furthest' (paling jauh).");
addQ("ing-k5-u10", 5, "Modals Obligation Must Keep Clean", "sulit", "All national park visitors ... keep the campsite clean to prevent forest fires.", ["Must", "Should not", "May not", "Would"], 0, "'Must' menyatakan keharusan mutlak menjaga kebersihan cagar alam.");
addQ("ing-k5-u11", 5, "Modals Prohibition You Must Not Touch", "sulit", "There is high-voltage wire: 'Danger! You ... touch the bare wire.'", ["Must not", "Must", "Should", "Can"], 0, "'Must not' adalah larangan keras karena bahaya keselamatan.");
addQ("ing-k5-u12", 5, "Reading Comprehension Renewable Energy", "sulit", "Read: 'Solar panels convert sunlight directly into clean electricity without producing harmful greenhouse gases. Many schools in Indonesia are now installing solar panels on their roofs to save energy and protect the environment.' What is the main benefit of solar panels according to the text?", ["They produce clean electricity without producing greenhouse gases", "They make roofs look dark", "They require gas fuel", "They work only in winter"], 0, "Manfaat utama panel surya adalah menghasilkan listrik bersih tanpa emisi gas rumah kaca.");
addQ("ing-k5-u13", 5, "Reading Comprehension Solar Panel Location", "sulit", "Based on the text: 'Many schools in Indonesia are now installing solar panels on their roofs.' Where are the solar panels being installed?", ["On school roofs", "Underground", "In the ocean", "Inside the library"], 0, "Teks menyatakan dipasang di atap sekolah ('on their roofs').");
addQ("ing-k5-u14", 5, "Reading Comprehension Inferred Purpose", "sulit", "Why do schools install solar panels on their roofs?", ["To save energy and protect the environment", "To make the building heavy", "To hide from the sun", "To spend money"], 0, "Tujuan instalasi panel surya adalah menghemat energi dan melindungi kelestarian lingkungan.");
addQ("ing-k5-u15", 5, "Adjective Polite vs Impolite", "sulit", "A well-mannered child who says 'please' and 'thank you' is polite. The opposite of 'polite' is ...", ["Impolite (rude)", "Kind", "Helpful", "Friendly"], 0, "Lawan kata sopan ('polite') adalah tidak sopan ('impolite' atau 'rude').");
addQ("ing-k5-u16", 5, "Adjective Patient vs Impatient", "sulit", "Waiting calmly in a long queue shows patience. Someone who gets angry waiting is ...", ["Impatient", "Patient", "Polite", "Gentle"], 0, "Lawan kata sabar ('patient') adalah tidak sabaran ('impatient').");
addQ("ing-k5-u17", 5, "Grammar Error Identification Singular Plural", "sulit", "Identify the grammatically INCORRECT sentence:", ["The childs are playing in the schoolyard.", "The children are playing in the schoolyard.", "The boy is playing with a ball.", "The girls are reading books."], 0, "'The childs' salah karena bentuk jamak dari 'child' adalah 'children'.");
addQ("ing-k5-u18", 5, "Grammar Error Identification Subject Verb", "sulit", "Which sentence contains a grammatical ERROR?", ["She do not like coffee.", "She does not like coffee.", "He likes tea.", "They do not drink milk."], 0, "'She do not' salah tata bahasa, seharusnya 'She does not'.");
addQ("ing-k5-u19", 5, "Reflexive Pronoun Himself", "sulit", "Budi looked at ... in the mirror before heading to the stage.", ["Himself", "Myself", "Herself", "Themselves"], 0, "Reflexive pronoun untuk laki-laki tunggal (Budi) adalah 'himself'.");
addQ("ing-k5-u20", 5, "Reflexive Pronoun Herself", "sulit", "Siti prepared the birthday gift box all by ... without any help.", ["Herself", "Himself", "Yourself", "Itself"], 0, "Reflexive pronoun untuk subjek perempuan (Siti) adalah 'herself'.");
addQ("ing-k5-u21", 5, "Reflexive Pronoun Themselves", "sulit", "The children cooked lunch by ... when their parents were at work.", ["Themselves", "Ourselves", "Himself", "Herself"], 0, "Reflexive pronoun untuk subjek jamak 'the children' adalah 'themselves'.");
addQ("ing-k5-u22", 5, "Relative Pronoun Who for Person", "sulit", "The doctor ... treated my broken wrist at the hospital is very gentle.", ["Who", "Which", "Where", "Whose"], 0, "Relative pronoun untuk menerangkan orang adalah 'who'.");
addQ("ing-k5-u23", 5, "Relative Pronoun Which for Things", "sulit", "The science book ... I borrowed from the library has colorful illustrations.", ["Which / That", "Who", "Whom", "Where"], 0, "Relative pronoun untuk benda adalah 'which' atau 'that'.");
addQ("ing-k5-u24", 5, "Relative Pronoun Where for Place", "sulit", "This is the library ... students read books quietly every afternoon.", ["Where", "Who", "Which", "Whose"], 0, "Relative pronoun untuk menerangkan tempat adalah 'where'.");
addQ("ing-k5-u25", 5, "Preposition During", "sulit", "Students are not allowed to chat loudly with friends ... the examination.", ["During", "Between", "Since", "For"], 0, "'During' menyatakan 'selama / saat berlangsungnya' ujian.");
addQ("ing-k5-u26", 5, "Preposition Since Time Point", "sulit", "My family has lived in this peaceful house ... 2018.", ["Since", "For", "During", "Until"], 0, "'Since' digunakan untuk titik awal waktu di masa lalu (sejak 2018).");
addQ("ing-k5-u27", 5, "Preposition For Duration", "sulit", "We have been studying English together in this classroom ... two hours.", ["For", "Since", "At", "In"], 0, "'For' digunakan untuk menyatakan durasi rentang waktu (selama dua jam).");
addQ("ing-k5-u28", 5, "Idiomatic Expression Piece of Cake", "sulit", "When a math test is very easy and simple to solve, native speakers say: 'That test was a ...!'", ["Piece of cake", "Cup of tea", "Drop in the ocean", "Apple of eye"], 0, "Ungkapan idiom 'a piece of cake' berarti sangat mudah sekali dilakukan.");
addQ("ing-k5-u29", 5, "Idiomatic Expression Once in a Blue Moon", "sulit", "An event that happens very rarely or almost never is described as happening ...", ["Once in a blue moon", "Every single day", "Out of the blue", "Time is money"], 0, "Idiom 'once in a blue moon' bermakna amat sangat jarang terjadi.");
addQ("ing-k5-u30", 5, "Conditional Sentence Type 0 General Fact", "sulit", "If you heat fresh water to 100 degrees Celsius, it ...", ["Boils", "Boiled", "Would boil", "Is boiling"], 0, "Zero conditional untuk fakta ilmiah alamiah menggunakan simple present: 'it boils'.");

console.log("Kelas 5 Bahasa Inggris ready: " + allQuestions.length + " questions.");

addQ("ing-k6-m01", 6, "Country and Nationality Indonesia", "mudah", "A citizen who comes from the country of Indonesia is called an ...", ["Indonesian", "Indian", "Indochinese", "Indonesianese"], 0, "Warga negara Indonesia dalam bahasa Inggris disebut 'Indonesian'.");
addQ("ing-k6-m02", 6, "Country and Nationality Japan", "mudah", "A person who comes from the country of Japan is ...", ["Japanese", "Japaner", "Japannish", "Japanian"], 0, "Warga negara Jepang adalah 'Japanese'.");
addQ("ing-k6-m03", 6, "Continent Asia", "mudah", "Indonesia, Japan, China, and Saudi Arabia are located in the continent of ...", ["Asia", "Europe", "Africa", "Australia"], 0, "Benua Asia adalah 'Asia'.");
addQ("ing-k6-m04", 6, "Continent Europe", "mudah", "England, France, Germany, and Italy are countries in the continent of ...", ["Europe", "Africa", "Asia", "America"], 0, "Benua Eropa adalah 'Europe'.");
addQ("ing-k6-m05", 6, "Space Astronaut", "mudah", "A brave person who is trained to travel and conduct research in outer space is an ...", ["Astronaut", "Astronomer", "Astrologer", "Pilot"], 0, "Orang yang menjelajahi antariksa adalah 'astronaut'.");
addQ("ing-k6-m06", 6, "Space Sun", "mudah", "The giant burning star at the center of our solar system that provides light and heat is the ...", ["Sun", "Moon", "Mars", "Comet"], 0, "Matahari adalah 'Sun'.");
addQ("ing-k6-m07", 6, "Environment Recycle", "mudah", "Mengolah kembali sampah plastik bekas menjadi barang baru yang berguna disebut ...", ["Recycle", "Reduce", "Reuse", "Replant"], 0, "Mendaur ulang sampah adalah 'recycle'.");
addQ("ing-k6-m08", 6, "Environment Save Energy", "mudah", "Tindakan mematikan lampu dan kran air saat tidak digunakan adalah wujud slogan ...", ["Save energy and water", "Waste energy", "Buy more electricity", "Turn on lights"], 0, "Menghemat energi adalah 'save energy'.");
addQ("ing-k6-m09", 6, "Congratulations Expression", "mudah", "Ungkapan bahasa Inggris yang tepat untuk memberi selamat kepada teman yang memenangkan lomba pidato adalah ...", ["Congratulations on your victory!", "I am sorry for your loss", "Get well soon", "Good luck next year"], 0, "'Congratulations!' diucapkan untuk memberi selamat atas kesuksesan.");
addQ("ing-k6-m10", 6, "Sympathy Expression", "mudah", "Ucapan bela sungkawa atau rasa simpati ketika mendengar kabar duka musibah teman adalah ...", ["I am sorry to hear that", "Congratulations", "Happy birthday", "Have a nice trip"], 0, "'I am sorry to hear that' menyatakan rasa simpati dan duka cita.");

addQ("ing-k6-s01", 6, "Narrative Text Orientation", "sedang", "The introductory opening part of a narrative story that introduces the characters, setting, and time is called the ...", ["Orientation", "Complication", "Resolution", "Reorientation"], 0, "Orientasi adalah tahap pengenalan tokoh, tempat, dan latar cerita.");
addQ("ing-k6-s02", 6, "Narrative Text Complication", "sedang", "The middle part of a narrative story where a major problem or conflict arises for the main character is the ...", ["Complication", "Orientation", "Resolution", "Title"], 0, "Komplikasi memuat timbulnya konflik atau krisis dalam cerita.");
addQ("ing-k6-s03", 6, "Narrative Text Resolution", "sedang", "The ending section of a narrative story where the problem is finally resolved happily or sadly is the ...", ["Resolution", "Complication", "Orientation", "Conflict"], 0, "Resolusi adalah bagian pemecahan masalah akhir cerita.");
addQ("ing-k6-s04", 6, "Procedure Text Sequence First", "sedang", "In a recipe procedure text, the step mentioned at the very beginning is introduced with the transition word ...", ["First", "Finally", "Next", "After that"], 0, "Langkah pertama dalam teks prosedur diawali kata 'First'.");
addQ("ing-k6-s05", 6, "Procedure Text Sequence Finally", "sedang", "The very last concluding step of making a cup of coffee in a procedural text begins with ...", ["Finally / Lastly", "First", "Secondly", "Before"], 0, "Langkah penutup terakhir diawali 'Finally' atau 'Lastly'.");
addQ("ing-k6-s06", 6, "Procedure Text Imperative Verb Boil", "sedang", "'... two cups of fresh water in a saucepan until it bubbles.' Kata kerja imperatif yang tepat adalah ...", ["Boil (didihkan)", "Freeze", "Eat", "Wash"], 0, "'Boil' berarti didihkan air sampai mendidih.");
addQ("ing-k6-s07", 6, "Procedure Text Imperative Verb Stir", "sedang", "'Add a spoonful of sugar and ... the tea well with a spoon.'", ["Stir (aduk)", "Cut", "Peel", "Bake"], 0, "'Stir' berarti mengaduk larutan dengan sendok.");
addQ("ing-k6-s08", 6, "Procedure Text Imperative Verb Chop", "sedang", "'... the fresh carrots and onions into small cubes on a cutting board.'", ["Chop (potong)", "Boil", "Fry", "Drink"], 0, "'Chop' atau 'cut' berarti memotong bahan masakan.");
addQ("ing-k6-s09", 6, "Conditional Sentence Type 1 Rain", "sedang", "If it ... heavily tomorrow morning, we will cancel our picnic to the lake.", ["Rains", "Rained", "Will rain", "Raining"], 0, "Conditional Type 1: If + Simple Present (rains), S + will + V1.");
addQ("ing-k6-s10", 6, "Conditional Sentence Type 1 Study", "sedang", "If Budi ... hard every day, he will pass the final national examination with flying colors.", ["Studies", "Study", "Studied", "Will study"], 0, "Subjek tunggal (Budi) dalam klausa If menggunakan simple present 'studies'.");
addQ("ing-k6-s11", 6, "Conditional Sentence Type 1 Win", "sedang", "If our school football team wins the final match, the principal ... a victory feast.", ["Will hold", "Held", "Holds", "Hold"], 0, "Klausa utama conditional type 1 menggunakan 'will' + V1: 'will hold'.");
addQ("ing-k6-s12", 6, "Environment Global Warming", "sedang", "The gradual increase in the average temperature of Earth's atmosphere caused by excessive greenhouse gases is ...", ["Global warming", "Ice age", "Photosynthesis", "Tsunami"], 0, "Pemanasan global adalah 'global warming'.");
addQ("ing-k6-s13", 6, "Environment Deforestation", "sedang", "The large-scale clearing and cutting down of tropical forests by humans is called ...", ["Deforestation", "Reforestation", "Afforestation", "Composting"], 0, "Penebangan hutan massal disebut 'deforestation'.");
addQ("ing-k6-s14", 6, "Environment Reforestation", "sedang", "Planting new trees on barren lands or harvested hills to restore natural forests is called ...", ["Reforestation (reboisasi)", "Deforestation", "Pollution", "Urbanization"], 0, "Penanaman kembali hutan gundul adalah 'reforestation' (reboisasi).");
addQ("ing-k6-s15", 6, "Country and Capital Jakarta", "sedang", "Jakarta is the historic and bustling economic capital city of the Republic of ...", ["Indonesia", "Malaysia", "Philippines", "Vietnam"], 0, "Jakarta adalah ibu kota Indonesia.");
addQ("ing-k6-s16", 6, "Country and Capital Tokyo", "sedang", "Tokyo is the ultra-modern capital city of ...", ["Japan", "South Korea", "China", "Thailand"], 0, "Tokyo adalah ibu kota negara Jepang ('Japan').");
addQ("ing-k6-s17", 6, "Country and Capital London", "sedang", "The famous Big Ben clock tower and Buckingham Palace are located in London, the capital of ...", ["The United Kingdom (England)", "The United States", "Canada", "Australia"], 0, "London adalah ibu kota Inggris (United Kingdom).");
addQ("ing-k6-s18", 6, "Direct to Indirect Speech Present to Past", "sedang", "Direct: He said, 'I am very tired.' Indirect: He said that he ... very tired.", ["Was", "Is", "Am", "Were"], 0, "Dalam kalimat tak langsung, to be present 'am' bergeser menjadi past 'was'.");
addQ("ing-k6-s19", 6, "Direct to Indirect Speech Like to Liked", "sedang", "Direct: Maya said, 'I like English.' Indirect: Maya said that she ... English.", ["Liked", "Likes", "Liking", "Will like"], 0, "Kata kerja 'like' berubah menjadi bentuk past 'liked' dalam reported speech.");
addQ("ing-k6-s20", 6, "Wishing Good Luck", "sedang", "Before your friend enters the examination room, you encourage him by saying: '... on your exam!'", ["Good luck", "Congratulations", "Good night", "I apologize"], 0, "'Good luck' diucapkan untuk mendoakan keberhasilan.");

addQ("ing-k6-u01", 6, "Reading Comprehension The Hare and The Tortoise", "sulit", "Read: 'A proud hare mocked a slow tortoise and challenged him to a foot race. The hare was so confident that he stopped to take a nap under a shady oak tree. Meanwhile, the tortoise walked steadily step by step without stopping until he crossed the finish line first.' Why did the hare lose the race?", ["Because he was overconfident and fell asleep during the race", "Because the tortoise pushed him into a hole", "Because the hare forgot the direction", "Because the tortoise ran faster than the wind"], 0, "Kelinci kalah karena sombong meremehkan lawan dan tertidur pulas saat lomba.");
addQ("ing-k6-u02", 6, "Reading Moral The Hare and The Tortoise", "sulit", "What is the famous English proverb and moral message taught by the story of the Tortoise and the Hare?", ["Slow and steady wins the race", "Never talk to turtles", "Fast animals are always best", "Sleeping under trees is healthy"], 0, "Pepatah 'Slow and steady wins the race' mengajarkan konsistensi dan pantang menyerah.");
addQ("ing-k6-u03", 6, "Reading Comprehension The Lion and The Mouse", "sulit", "Read: 'A tiny mouse accidentally woke a sleeping lion. The lion spared the mouse's life. Later, when the lion was trapped in a hunter's rope net, the little mouse chewed the thick ropes with his sharp teeth and freed the lion.' What moral value is highlighted in this fable?", ["Even the smallest friend can be of great help in times of need", "Mice should fear lions", "Hunters always win", "Lions never sleep"], 0, "Kebaikan kecil dibalas dengan pertolongan besar saat dibutuhkan.");
addQ("ing-k6-u04", 6, "Complex Conjunction Although Contrast", "sulit", "... it was raining heavily with strong winds, the brave firefighters continued putting out the house fire.", ["Although (maupun / meskipun)", "Because", "Therefore", "Unless"], 0, "'Although' menyatakan perlawanan keadaan (meskipun hujan deras).");
addQ("ing-k6-u05", 6, "Complex Conjunction In Order To Purpose", "sulit", "Students should study their lessons regularly ... achieve excellent grades in the final examination.", ["In order to", "Although", "Because of", "Instead of"], 0, "'In order to' bermakna 'agar / dengan tujuan untuk'.");
addQ("ing-k6-u06", 6, "Complex Conjunction Unless Condition", "sulit", "You cannot borrow books from the municipal library ... you present your valid membership card.", ["Unless (kecuali jika)", "If", "Because", "Although"], 0, "'Unless' bermakna 'kecuali jika' (if not).");
addQ("ing-k6-u07", 6, "Complex Conjunction Whereas Comparison", "sulit", "Budi loves reading science fiction novels, ... his younger brother prefers playing football outside.", ["Whereas (sedangkan / sebaliknya)", "Because", "So that", "Unless"], 0, "'Whereas' digunakan untuk memperbandingkan dua hal yang berlawanan.");
addQ("ing-k6-u08", 6, "Reading Comprehension Indonesian Biodiversity", "sulit", "Read: 'Indonesia is home to the world's third-largest tropical rainforest and boasts extraordinary biodiversity, including endemic species like the Komodo dragon, Javan rhinoceros, and the giant Rafflesia arnoldii flower.' Which flower is mentioned as endemic to Indonesia in the text?", ["Rafflesia arnoldii", "Sakura", "Tulip", "Rose"], 0, "Teks menyebutkan bunga raksasa endemik Indonesia 'Rafflesia arnoldii'.");
addQ("ing-k6-u09", 6, "Reading Comprehension Endemic Fauna", "sulit", "Based on the text: 'including endemic species like the Komodo dragon, Javan rhinoceros, and Rafflesia arnoldii.' Which reptile is mentioned as an endemic species?", ["Komodo dragon", "Bengal tiger", "Kangaroo", "Panda"], 0, "Reptil purba endemik yang disebutkan dalam kutipan adalah 'Komodo dragon'.");
addQ("ing-k6-u10", 6, "Reading Inferred Meaning Biodiversity", "sulit", "The word 'biodiversity' in the passage refers to the ...", ["Rich variety of animal and plant life within a natural ecosystem", "Number of wooden houses", "Speed of rivers", "Types of vehicles"], 0, "Biodiversitas bermakna keanekaragaman hayati flora dan fauna di suatu ekosistem.");
addQ("ing-k6-u11", 6, "Idiom Break a Leg", "sulit", "Before an actor or musician walks onto the stage for a musical performance, friends often say 'Break a leg!' which means ...", ["Good luck! (semoga sukses)", "Break your bone", "Do not perform", "Fall down"], 0, "Idiom dunia pementasan 'Break a leg!' bermakna 'Good luck! / Semoga sukses!'.");
addQ("ing-k6-u12", 6, "Idiom Under the Weather", "sulit", "When someone says 'I am feeling a bit under the weather today', it means they are ...", ["Feeling sick or slightly unwell", "Standing in the rain", "Looking at the clouds", "Very happy"], 0, "Idiom 'under the weather' berarti merasa kurang enak badan / sakit ringan.");
addQ("ing-k6-u13", 6, "Idiom Cost an Arm and a Leg", "sulit", "That luxury sports car costs an arm and a leg! This idiom means the car is ...", ["Extremely expensive", "Free of charge", "Very cheap", "Broken"], 0, "'Cost an arm and a leg' adalah idiom untuk barang yang harganya selangit (sangat mahal).");
addQ("ing-k6-u14", 6, "Identifying Correct Passive Sentence", "sulit", "Which sentence is written in the CORRECT passive voice?", ["The Mona Lisa was painted by Leonardo da Vinci.", "The Mona Lisa is paint by Leonardo da Vinci.", "The Mona Lisa were painted by Leonardo da Vinci.", "The Mona Lisa was painting by Leonardo da Vinci."], 0, "Kalimat pasif lampau yang tepat: Subject + was + V3 ('was painted').");
addQ("ing-k6-u15", 6, "Reported Speech Said That Had", "sulit", "Direct: 'I finished my homework,' said Ali. Reported: Ali said that he ... his homework.", ["Had finished", "Have finished", "Finishing", "Will finish"], 0, "Bentuk lampau V2 'finished' bergeser menjadi past perfect 'had finished' dalam reported speech.");
addQ("ing-k6-u16", 6, "Modal Deduction Must Be Tired", "sulit", "Farhan has been running a 10-kilometer marathon under the hot sun. He ... very exhausted right now.", ["Must be (pasti)", "Cannot be", "May not be", "Should not be"], 0, "'Must be' menyatakan deduksi kepastian logis (pasti sangat lelah).");
addQ("ing-k6-u17", 6, "Modal Deduction Cannot Be True", "sulit", "Budi was in Surabaya yesterday. It ... Budi you saw in Jakarta yesterday morning.", ["Cannot have been", "Must be", "Should be", "Will be"], 0, "'Cannot have been' menyatakan kemustahilan suatu peristiwa masa lalu.");
addQ("ing-k6-u18", 6, "Prefix Re- Meaning", "sulit", "The prefix 're-' in words like 'rewrite', 'rebuild', and 'recycle' means to do the action ...", ["Again (kembali)", "Never", "Before", "Against"], 0, "Awalan 're-' berarti melakukan tindakan kembali (again).");
addQ("ing-k6-u19", 6, "Prefix Un- Meaning", "sulit", "The prefix 'un-' in words like 'unhappy', 'unfair', and 'unkind' means ...", ["Not / Opposite of (tidak)", "Very much", "Always", "Together"], 0, "Awalan 'un-' bermakna negasi atau 'tidak'.");
addQ("ing-k6-u20", 6, "Suffix -ful Meaning", "sulit", "The suffix '-ful' in words like 'helpful', 'hopeful', and 'careful' means ...", ["Full of / having the quality of", "Without", "Past time", "One who does"], 0, "Akhiran '-ful' bermakna penuh dengan kualitas tersebut (full of).");
addQ("ing-k6-u21", 6, "Suffix -less Meaning", "sulit", "The suffix '-less' in words like 'hopeless', 'careless', and 'fearless' means ...", ["Without (tanpa)", "Full of", "Able to", "Result of"], 0, "Akhiran '-less' berarti tanpa / ketiadaan hal tersebut.");
